// Drives the window.__greybox detection seam: a CoK-DOS list must register as
// champions-of-krynn/DOS, and a junk list must NOT register. Independent of game
// data, so this runs on a fresh clone.
async function runDetection(browser) {
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  let lib = [];
  let junkRejected = false;
  try {
    await page.goto(`${BASE}/`, { waitUntil: 'networkidle2', timeout: 45000 });
    await page.waitForFunction('window.__greybox && typeof window.__greybox.addFromEntries === "function"', { timeout: 45000 });
    await page.evaluate((files) => window.__greybox.addFromEntries('CoK-test', files), COK_DOS_FILES);
    const junkMatch = await page.evaluate((files) => window.__greybox.addFromEntries('junk', files), JUNK_FILES);
    junkRejected = junkMatch === null;
    lib = await page.evaluate('window.__greybox.getLibrary()');
  } catch (e) {
    errors.push(`detection: ${e.message}`);
  }
  // M47.S1 — the Library list's meta line now names the real container format (DAX for CoK-DOS),
  // not just platform/graphicSet/confidence.
  const metaText = await page.evaluate(() => document.querySelector('.cat-meta')?.textContent ?? '');
  const containerShown = metaText.includes('DAX');
  await page.close();
  const cok = Array.isArray(lib) ? lib.find((m) => m.profileId === 'champions-of-krynn' && m.platform === 'DOS') : null;
  const pass = !!cok && junkRejected && (Array.isArray(lib) && lib.length === 1) && containerShown && errors.length === 0;
  if (!pass && containerShown === false) errors.push(`containerShown=${containerShown} metaText="${metaText}"`);
  return { id: 'detection', label: 'Library: fingerprint CoK-DOS, reject junk', rendered: lib.length, min: 1, errors, bad: [], pass };
}

// M5.S6 — drives the same __greybox seam with the broader Gen1 roster's synthetic file lists
// and asserts each registers under its own profileId/ruleset, distinctly from Krynn and from each
// other. Independent of game data, so this runs on a fresh clone too.
async function runBroaderRoster(browser) {
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  let lib = [];
  try {
    await page.goto(`${BASE}/`, { waitUntil: 'networkidle2', timeout: 45000 });
    await page.waitForFunction('window.__greybox && typeof window.__greybox.addFromEntries === "function"', { timeout: 45000 });
    for (const [name, files] of BROADER_ROSTER_FOLDERS) {
      await page.evaluate((n, f) => window.__greybox.addFromEntries(n, f), name, files);
    }
    lib = await page.evaluate('window.__greybox.getLibrary()');
  } catch (e) {
    errors.push(`broader-roster: ${e.message}`);
  }
  await page.close();
  const ids = Array.isArray(lib) ? lib.map((m) => m.profileId) : [];
  const expected = BROADER_ROSTER_FOLDERS.map(([id]) => id);
  const allFound = expected.every((id) => ids.includes(id));
  const distinct = new Set(ids).size === ids.length;
  const pass = allFound && distinct && ids.length === expected.length && errors.length === 0;
  return { id: 'broader-roster', label: 'Library: fingerprint broader synthetic Gen1 roster (M5.S6)', rendered: ids.length, min: expected.length, errors, bad: [], pass };
}

// NWN is intentionally a manifest-backed Library route, not a playable dungeon route yet:
// detected Library entry -> onLibrarySelect() -> ?game=neverwinter-nights-dos -> game dashboard.
async function runNwnLibraryGameView(browser) {
  const page = await browser.newPage();
  const errors = [];
  const bad = [];
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  let rendered = -1;
  let matched = false;
  let visible = false;
  let routed = false;
  let headerText = '';
  let statusText = '';
  try {
    await page.goto(`${BASE}/`, { waitUntil: 'networkidle2', timeout: 45000 });
    await page.waitForFunction('window.__greybox && typeof window.__greybox.addFromEntries === "function"', { timeout: 45000 });
    const match = await page.evaluate((files) => window.__greybox.addFromEntries('picked-nwn', files), NWN_DOS_FILES);
    matched = !!match && match.profileId === 'neverwinter-nights-dos' && match.platform === 'DOS';
    await page.waitForSelector('.lib-entry', { timeout: 10000 });
    visible = await page.evaluate(() =>
      [...document.querySelectorAll('.lib-entry')].some((el) => /Neverwinter Nights \(DOS\/AOL\)/i.test(el.textContent ?? '')),
    );
    await page.evaluate('window.__rendered = undefined');
    await page.click('.lib-entry');
    // 2026-07-21: NWN was promoted from an asset dashboard to a real walkable ?explore=nwn route
    // (docs/engine/research/neverwinter-nights-dos-eclinit.md) — the same promotion Pools of
    // Darkness got. Picking the Library entry now routes into the explore view, not the old
    // generic per-game dashboard. This test's `addFromEntries` call only supplies filenames (no
    // real asset bytes, per `window.__greybox`'s own doc comment on the plain vs *WithAssets
    // seams) so the picked-folder `assetSource` is `NULL_ASSET_SOURCE` and the real dungeon load
    // legitimately can't succeed — the same "no real data" outcome every other data-dependent e2e
    // case in this suite tolerates (`window.__explore || window.__rendered === 0`). What THIS test
    // proves is detection + Library visibility + the routing side effect; a real user's own picked
    // folder carries real bytes and is covered instead by explore-nwn.
    await page.waitForFunction('window.__explore || window.__rendered === 0', { timeout: 45000 });
    rendered = await page.evaluate('window.__rendered');
    routed = await page.evaluate(() => location.search === '?explore=nwn');
    headerText = await page.evaluate(() => document.querySelector('.game-header')?.textContent ?? '');
    statusText = await page.evaluate(() => document.querySelector('#status')?.textContent ?? '');
  } catch (e) {
    errors.push(`nwn-library-game-view: ${e.message}`);
  }
  await page.close();
  // R5 round 30: the verdict read `rendered >= 0`, which is true of every non-negative number and
  // so could not distinguish this route working from it failing. `headerText` and `statusText` were
  // captured and then never asserted -- a dead assignment that reads like coverage.
  //
  // MEASURED: this route renders exactly 0 tiles and reports
  // "Could not load dungeon: 8X8D.DAX: not found in the selected folder". That is the CORRECT
  // outcome and the comment above explains why: `addFromEntries` supplies filenames only, so the
  // picked-folder assetSource is NULL_ASSET_SOURCE and there are no bytes to draw. Pinning the
  // exact number and the exact reason is what makes this falsifiable: if the route ever starts
  // drawing, or starts failing for a DIFFERENT reason, this goes red instead of silently passing.
  const renderedOk = rendered === 0;
  const statusOk = /Could not load dungeon: 8X8D\.DAX: not found in the selected folder/.test(statusText);
  if (!renderedOk || !statusOk) {
    errors.push(`nwn-library-game-view-outcome: rendered=${JSON.stringify(rendered)} status=${JSON.stringify(statusText)}`);
  }
  const pass = matched && visible && routed && renderedOk && statusOk && errors.length === 0 && bad.length === 0;
  return {
    id: 'nwn-library-game-view',
    label: 'Library: NWN visible/selectable and routes into the explore view',
    rendered,
    min: 0,
    errors: pass ? [] : [...errors, `matched=${matched} visible=${visible} routed=${routed} header="${headerText}" status="${statusText}"`],
    bad,
    pass,
  };
}

// The asset browser advertised "monster sprites" for Pools of Darkness and Treasures and the
// loader could not open a single one of their SPRIT blocks (HANDOFF twenty-third: a
// `frameCount - 1` word was read as a required zero). This is the browser-side proof that the fix
// is reachable through the real manifest route, not only through the engine unit test — the exact
// hazard the "solved but unwired" note is about. Frame totals are the measured retail counts:
// Pools 29 blocks x 3 view-sizes = 87, Treasures 13 x 3 = 39.
/**
 * Every bundled manifest is reachable from the UI.
 *
 * `GAME_IDS` in `gameview.ts` is both the sidebar picker and the gate the Library checks before
 * routing a detected install (`DETECTED_TO_MANIFEST`). It drifted: four complete manifests
 * (`death-knights-dos`, `pools-of-darkness`, `treasures-of-the-savage-frontier`,
 * `forgotten-realms-unlimited-adventures`) shipped in the bundle and were reachable only by typing
 * `?game=<id>`. A detected Pools install got "Playable rendering for this variant arrives in a
 * later milestone" while its manifest was sitting right there.
 *
 * The list on disk is the source of truth here, so adding a manifest without wiring it fails.
 */
async function runManifestPickerCoverage(browser) {
  const errors = [];
  const bad = [];
  const onDisk = readdirSync(GAMES_DIR).filter((f) => f.endsWith('.json')).map((f) => f.slice(0, -5)).sort();
  const page = await browser.newPage();
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  let inPicker = [];
  try {
    await page.goto(`${BASE}/`, { waitUntil: 'networkidle2', timeout: 90000 });
    await page.waitForSelector('.game-pick', { timeout: 60000 });
    // `.game-pick` is also worn by sidebar entries that are not manifest picks (they carry no
    // `data-game-id`), so key on the dataset attribute the picker sets from GAME_IDS.
    inPicker = (await page.evaluate(() =>
      [...document.querySelectorAll('.game-pick[data-game-id]')].map((el) => el.dataset.gameId),
    )).sort();
  } catch (e) {
    errors.push(`manifest-picker-coverage: ${e.message}`);
  }
  await page.close();

  const missing = onDisk.filter((id) => !inPicker.includes(id));
  const phantom = inPicker.filter((id) => !onDisk.includes(id));
  if (missing.length) errors.push(`manifests with no picker entry: ${missing.join(', ')}`);
  if (phantom.length) errors.push(`picker entries with no manifest file: ${phantom.join(', ')}`);
  // The control: this only means something if the disk read actually found the manifests.
  if (onDisk.length < 10) errors.push(`only ${onDisk.length} manifests found on disk — the read is broken, not the wiring`);

  const pass = errors.length === 0 && bad.length === 0;
  return {
    id: 'manifest-picker-coverage',
    label: 'Every bundled game manifest has a picker entry',
    rendered: inPicker.length,
    min: onDisk.length,
    errors: pass ? [] : [...errors, `onDisk=${onDisk.join(',')}`, `inPicker=${inPicker.join(',')}`],
    bad,
    pass,
  };
}

/**
 * Buck Rogers: Countdown to Doomsday, the tenth DOS title and the first non-AD&D one.
 *
 * The install is `D:/Games/Emulator/DOS/Goldbox/BuckRogers1-CountdownToDoomsday`, outside the repo
 * and outside GOG. Every count below is measured from the engine's own routing, not from the
 * Python reference decoder — the two disagree about `8X8D*` by a factor of 256, which is how the
 * previous round shipped a wrong number.
 */
// Round 33 R5 pinned ONE regex here for both Buck titles, on the reasoning that they ship the
// same byte-identical eight-song `MUSIC.DAX`. Round 34 R4 showed the shared pin was hiding the
// difference that matters: Matrix Cubed's own executable never opens `MUSIC.DAX` by name, and
// scores instead with three Miles/AIL `.XMI` files (`BUCKA/B/C.XMI` beside the same `FATV9` bank
// DQK uses). Its `MUSIC.DAX` is a leftover of the shared Gen1 codebase.
//
// So the two titles get two rows, and the regexes are each other's control:
//  - Countdown really is GLBR-scored: 8 songs, 1959 events, 31 channel streams -- unchanged.
//  - Matrix reads XMI: 21 songs, 5702 events, 95 channels, and the word GLBR must NOT appear.
// A regression that dropped the manifest's `.XMI` rows would fall back to the GLBR census and put
// Countdown's exact numbers on Matrix's header -- which is precisely what MATRIX_MUSIC_ROW's
// negative half catches. The numbers are pinned exactly, not as `/\d+ songs/`: a census that
// silently fell to 0 would still render a row that a loose regex would accept.
// Mutation-checked by editing each expected event count and watching only that case go red.
const MUSIC_ROW = /8 GLBR songs\s*[·•|]?\s*1959 events\s*[·•|]?\s*31 channels/;
const MATRIX_MUSIC_ROW = /21 XMI songs\s*[·•|]?\s*5702 events\s*[·•|]?\s*95 channels/;

async function runBuckRogersView(browser) {
  const errors = [];
  const bad = [];
  const EXPECT = [
    { file: 'TITLE', frames: 4 },
    { file: 'PIC1 ', frames: 11 },
    { file: 'PIC2 ', frames: 17 },
    { file: 'CHARS', frames: 72 },
    { file: 'COMSPR', frames: 50 },
    { file: 'SPRIT1', frames: 3 },
    { file: 'SPRIT3', frames: 30 },
    { file: 'MARSCOM', frames: 42 },
    { file: 'VENUSCOM', frames: 44 },
    { file: 'HITEK', frames: 53 },
    { file: 'LOTEK', frames: 52 },
    { file: 'SHIPS', frames: 35 },
    // R4 decoded `8X8D1.DAX#201` as a third block (a Gen1 text-glyph 'font' sheet) alongside the
    // file's two existing tile sheets, but `loadGame.ts`'s `framesFromDecoded` DELIBERATELY excludes
    // `kind: 'font'` blocks from this whole-game dashboard (`if (b.kind === 'font') { skipped++; }`,
    // by design — a text-glyph sheet is not a dungeon tile/sprite/scene the dashboard categorizes,
    // and it would also shift index-0 of the cross-platform GraphicSet tile8x8 category if it were
    // folded in there). The font sheet is visible only through the single-asset raw browser
    // (`main.ts`'s generic per-block DAX viewer, which reads `DaxBlock.image` directly), NOT here.
    // So this row correctly STAYS at 2, not 3 — pinned explicitly so a future change to either side
    // of that design split (the exclusion, or the font decode itself) shows up as a count change
    // here rather than silently drifting. (The original round plan for this item expected 2->3 and
    // TOTAL 489->490; measured against the actual shipped code, both are wrong — see the report.)
    { file: '8X8D1', frames: 2 },
  ];
  const TOTAL = 489;
  let rendered = 0;
  let rows = {};
  let music = '';
  const page = await browser.newPage();
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  try {
    await page.goto(`${BASE}/?game=buck-rogers-countdown-to-doomsday`, { waitUntil: 'networkidle2', timeout: 90000 });
    await page.waitForFunction('window.__rendered !== undefined', { timeout: 120000 });
    rendered = await page.evaluate(() => window.__rendered);
    rows = await page.evaluate((names) => {
      const out = {};
      for (const name of names) {
        const head = [...document.querySelectorAll('.file-head')].find((el) =>
          (el.querySelector('.file-name')?.textContent?.trim() ?? '').startsWith(name),
        );
        if (!head) { out[name] = null; continue; }
        let grid = head.nextElementSibling;
        while (grid && !grid.classList.contains('frame-grid') && !grid.classList.contains('file-head')) {
          grid = grid.nextElementSibling;
        }
        out[name] = grid?.classList.contains('frame-grid') ? grid.querySelectorAll('canvas').length : 0;
      }
      return out;
    }, EXPECT.map((w) => w.file));
    // Round 33 R5: the GLBR music decoder was correct and reachable by nothing. `loadGame` now
    // reports a `{songs, events, channels}` census and `gameview.ts` renders it in the header,
    // so this is the assertion that makes the decode SHIPPED rather than merely tested --
    // the engine unit test proves the numbers, this proves a browser actually gets them.
    music = await page.evaluate(
      () => document.querySelector('.game-header')?.textContent?.trim() ?? '',
    );
  } catch (e) {
    errors.push(`buck-rogers-view: ${e.message}`);
  }
  await page.close();

  for (const want of EXPECT) {
    if (rows[want.file] === null || rows[want.file] === undefined) { errors.push(`no ${want.file} row`); continue; }
    if (rows[want.file] !== want.frames) errors.push(`${want.file}: ${rows[want.file]} frame cards (expected ${want.frames})`);
  }
  if (rendered !== TOTAL) errors.push(`whole manifest rendered ${rendered} frames (expected ${TOTAL})`);
  if (!MUSIC_ROW.test(music)) errors.push(`music census row missing/wrong: ${JSON.stringify(music.slice(-120))}`);

  const pass = errors.length === 0 && bad.length === 0;
  return {
    id: 'buck-rogers-view',
    label: 'Buck Rogers: Countdown to Doomsday renders from its own DOS install',
    rendered,
    min: TOTAL,
    errors: pass ? [] : [...errors, JSON.stringify(rows)],
    bad,
    pass,
  };
}

/**
 * Buck Rogers: Countdown to Doomsday, Amiga graphic set (WHDLoad unpacked dump).
 *
 * The install is `D:/Games/Emulator/Amiga/WHDLoad/WHDLoadPacks/WHDLoad Collection/
 * Games-WHDLoad/unpacked/BuckRogersCountdownDday/data`, outside the repo. Like `buck-rogers-view`
 * above (no `dataAbsent` disjunct in `pass`), this case FAILS rather than SKIPs when that `D:` path
 * is absent — kept consistent with that precedent rather than inventing a new skip convention for
 * one manifest.
 *
 * The PIC and SPRIT rows are the point: `apps/web/games/buck-rogers-amiga.json`'s own notes record
 * that these are 6-byte sub-frame-index families whose entry counts (10/9/17 for pic1/2/3; 4/16/11
 * for sprit1/2/3) are NOT their frame counts (36/21/49; 12/48/33) — `loadGame.ts`'s DAA `index`
 * branch pushes every decoded distance frame per entry, not just one. Asserting the entry counts
 * here instead would silently accept a regression to "primary frame only".
 */
/**
 * Buck Rogers: Matrix Cubed — the thirteenth capability profile and the sixteenth manifest.
 *
 * The install is the DOS release extracted (once, by `tools/matrix_cubed_extract.py`) into
 * git-ignored `matrixcubed_extracted/`; the source `.7z` on the external drive is never written to
 * and nothing auto-extracts. Like `buck-rogers-view`, this case FAILS rather than SKIPs when the
 * extraction is absent, matching that precedent.
 *
 * Every count below was MEASURED from the engine's own routing, not copied from the Python
 * reference decoder or from Countdown's numbers. Two rows are worth naming because they differ
 * from the sibling game and an unexplained difference is still a measurement: `8X8D1` renders 12
 * sheets here against Countdown's 2, and `SPRIT1` renders 69 against Countdown's 3. Neither is
 * explained in this case — they are pinned as observed so that a decoder change moves them
 * visibly instead of silently.
 *
 * The zero rows are pinned deliberately too. `GEO1`, `ECL1`, `WALLDEF1`, the MON/ITEM tables,
 * `MUSIC`, `GAME.OVR` and `MATRIX.CFG` carry `decode:false` in the manifest: they are listed so
 * the dashboard shows the whole corpus, but they must render no frames. A non-zero there would
 * mean data was being drawn as art.
 */
async function runMatrixCubedView(browser) {
  const errors = [];
  const bad = [];
  const EXPECT = {
    'TITLE (title screen)': 4,
    'BIGPIC1 (scenes)': 6,
    'PIC1 (animated scenes)': 102,
    'PIC7 (animated scenes)': 1,
    'PIC8 (animated scenes)': 1,
    'CPIC1 (combat portraits)': 108,
    'CHARS (character portraits)': 72,
    'BACK1 (combat backdrops)': 20,
    'BORDERS (frame backdrops)': 12,
    '8X8D0 (8x8 tile sheet)': 1,
    '8X8D1 (8x8 tile sheet)': 12,
    'COMSPR (combat sprites)': 50,
    'SPRIT1 (monster sprites)': 69,
    'MARSCOM (Mars combat set)': 42,
    'VENUSCOM (Venus combat set)': 44,
    'HITEK (high-tech item icons)': 53,
    'LOTEK (low-tech item icons)': 52,
    'SHIPS (spacecraft art + stats)': 35,
    'CURSOR (UI cursor)': 1,
    'GEO1 (map data)': 0,
    'ECL1 (event scripts)': 0,
    'WALLDEF1 (wall definitions)': 0,
    'MON0CHA (monster tables)': 0,
    'MON0ITM (monster items)': 0,
    'MON0SPC (monster specials)': 0,
    'ITEM0 (item table)': 0,
    // Round 34 R4/Phase B: the real score. These eleven rows render no frames, but pinning them
    // by name is what makes "the manifest lists Matrix's actual Miles/AIL stack" an e2e fact
    // rather than a claim in a note -- and the exact-set check below means dropping any of them
    // fails here, not silently.
    'BUCKA (music, Miles AIL XMIDI)': 0,
    'BUCKB (music, Miles AIL XMIDI)': 0,
    'BUCKC (music, Miles AIL XMIDI)': 0,
    'FATV9.AD (Miles instrument bank)': 0,
    'FATV9.BNK (Miles instrument bank companion)': 0,
    'FATV9.CAT (Miles instrument bank companion)': 0,
    'ADLIB.ADV (Miles hardware driver)': 0,
    'MT32MPU.ADV (Miles hardware driver)': 0,
    'PCSPKR.ADV (Miles hardware driver)': 0,
    'SBFM.ADV (Miles hardware driver)': 0,
    'TANDY.ADV (Miles hardware driver)': 0,
    // Relabelled in the same patch: this file is a leftover of the shared Gen1 codebase, not this
    // title's music, and the label says so.
    'MUSIC (music banks, leftover)': 0,
    'GAME.OVR (overlay pool)': 0,
    'MATRIX.CFG (install config)': 0,
  };
  const TOTAL = 685;
  let rendered = 0;
  let rows = {};
  let music = '';
  const page = await browser.newPage();
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  try {
    await page.goto(`${BASE}/?game=buck-rogers-matrix-cubed`, { waitUntil: 'networkidle2', timeout: 90000 });
    await page.waitForFunction('window.__rendered !== undefined', { timeout: 120000 });
    rendered = await page.evaluate(() => window.__rendered);
    rows = await page.evaluate(() => {
      const out = {};
      for (const head of document.querySelectorAll('.file-head')) {
        const name = head.querySelector('.file-name')?.textContent?.trim() ?? '?';
        let grid = head.nextElementSibling;
        while (grid && !grid.classList.contains('frame-grid') && !grid.classList.contains('file-head')) grid = grid.nextElementSibling;
        out[name] = grid?.classList.contains('frame-grid') ? grid.querySelectorAll('canvas').length : 0;
      }
      return out;
    });
    music = await page.evaluate(
      () => document.querySelector('.game-header')?.textContent?.trim() ?? '',
    );
  } catch (e) {
    errors.push(`matrix-cubed-view: ${e.message}`);
  }
  await page.close();

  for (const [name, want] of Object.entries(EXPECT)) {
    if (rows[name] === undefined) { errors.push(`no ${name} row`); continue; }
    if (rows[name] !== want) errors.push(`${name}: ${rows[name]} frame cards (expected ${want})`);
  }
  // The row set is pinned as an exact set, not a subset: a new file appearing in the manifest
  // without a pin here would otherwise ride along uncounted.
  for (const name of Object.keys(rows)) {
    if (EXPECT[name] === undefined) errors.push(`unpinned row appeared: ${name} (${rows[name]})`);
  }
  if (rendered !== TOTAL) errors.push(`whole manifest rendered ${rendered} frames (expected ${TOTAL})`);
  // NOT the same census as Countdown, and that is the point (round 34 R4). Two-sided: the XMI
  // numbers must be present AND Countdown's GLBR numbers must not be, so a silent fallback to the
  // leftover byte-identical MUSIC.DAX fails here rather than reading as a pass.
  if (!MATRIX_MUSIC_ROW.test(music)) errors.push(`XMI music census row missing/wrong: ${JSON.stringify(music.slice(-160))}`);
  if (MUSIC_ROW.test(music)) errors.push(`Matrix showed Countdown's GLBR census -- .XMI manifest rows lost? ${JSON.stringify(music.slice(-160))}`);

  const pass = errors.length === 0 && bad.length === 0;
  return {
    id: 'matrix-cubed-view',
    label: 'Buck Rogers: Matrix Cubed renders from its extracted DOS install',
    rendered,
    min: TOTAL,
    errors: pass ? [] : [...errors, JSON.stringify(rows)],
    bad,
    pass,
  };
}

async function runBuckRogersAmigaView(browser) {
  const errors = [];
  const bad = [];
  const EXPECT = [
    { file: 'TTL1', frames: 1 },
    { file: 'BIGPIC1', frames: 3 },
    { file: 'BIGPIC2', frames: 3 },
    { file: 'BIGPIC3', frames: 3 },
    { file: 'PIC0', frames: 6 },
    { file: 'PIC1', frames: 36 },
    { file: 'PIC2', frames: 21 },
    { file: 'PIC3', frames: 49 },
    { file: 'BACK1', frames: 4 },
    { file: 'BACK2', frames: 6 },
    { file: 'BACK3', frames: 6 },
    { file: 'BORDERS', frames: 1 },
    { file: 'SPACETVL', frames: 1 },
    { file: 'CPIC1', frames: 14 },
    { file: 'CPIC2', frames: 50 },
    { file: 'CPIC3', frames: 40 },
    { file: '8X8D0', frames: 5 },
    { file: '8X8D1', frames: 8 },
    { file: '8X8D2', frames: 12 },
    { file: '8X8D3', frames: 12 },
    { file: 'COMSPR', frames: 50 },
    { file: 'SPRIT1', frames: 12 },
    { file: 'SPRIT2', frames: 48 },
    { file: 'SPRIT3', frames: 33 },
    { file: 'MARSCOM0', frames: 1 },
    { file: 'VENUSCOM0', frames: 1 },
    { file: 'HITEK0', frames: 1 },
    { file: 'LOTEK0', frames: 1 },
    { file: 'SHIPS', frames: 23 },
  ];
  const TOTAL = 454;
  let rendered = 0;
  let rows = {};
  const page = await browser.newPage();
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  try {
    await page.goto(`${BASE}/?game=buck-rogers-amiga`, { waitUntil: 'networkidle2', timeout: 90000 });
    await page.waitForFunction('window.__rendered !== undefined', { timeout: 120000 });
    rendered = await page.evaluate(() => window.__rendered);
    rows = await page.evaluate((names) => {
      const out = {};
      for (const name of names) {
        const head = [...document.querySelectorAll('.file-head')].find((el) =>
          (el.querySelector('.file-name')?.textContent?.trim() ?? '').startsWith(name),
        );
        if (!head) { out[name] = null; continue; }
        let grid = head.nextElementSibling;
        while (grid && !grid.classList.contains('frame-grid') && !grid.classList.contains('file-head')) {
          grid = grid.nextElementSibling;
        }
        out[name] = grid?.classList.contains('frame-grid') ? grid.querySelectorAll('canvas').length : 0;
      }
      return out;
    }, EXPECT.map((w) => w.file));
  } catch (e) {
    errors.push(`buck-rogers-amiga-view: ${e.message}`);
  }
  await page.close();

  for (const want of EXPECT) {
    if (rows[want.file] === null || rows[want.file] === undefined) { errors.push(`no ${want.file} row`); continue; }
    if (rows[want.file] !== want.frames) errors.push(`${want.file}: ${rows[want.file]} frame cards (expected ${want.frames})`);
  }
  if (rendered !== TOTAL) errors.push(`whole manifest rendered ${rendered} frames (expected ${TOTAL})`);

  const pass = errors.length === 0 && bad.length === 0;
  return {
    id: 'buck-rogers-amiga-view',
    label: 'Buck Rogers: Countdown to Doomsday (Amiga) renders from its own WHDLoad install',
    rendered,
    min: TOTAL,
    errors: pass ? [] : [...errors, JSON.stringify(rows)],
    bad,
    pass,
  };
}


/**
 * Round 31 R6 - the three Amiga GLIB manifests landed this round: `dark-queen-amiga`,
 * `pools-amiga`, `curse-amiga`, all read from the never-vendored WHDLoad tree.
 *
 * These three cases read the dashboard's rows POSITIONALLY - the full ordered list of
 * `.file-head` rows and their frame-card counts - instead of looking each row up by a name prefix
 * the way `buck-rogers-amiga-view` does. That is not a style preference. Curse's manifest carries
 * TWO rows both labelled "8X8D (shared tiles)", holding 65 frames and 1260 frames; a
 * `startsWith`-based lookup returns whichever comes first and would silently score the 1260-frame
 * row against the 65-frame pin, or vice versa. Reading the whole ordered list also means a row
 * APPEARING or DISAPPEARING fails, which a per-name lookup cannot see.
 *
 * Every count is exact, and the zero rows are pinned with the rest rather than skipped: the
 * `decode:false` data rows (ECL / GEO / ITEM / MON* / SOUNDS / STRINGS / WALLDEF) must render
 * nothing, and that assertion is non-vacuous only because the same ordered comparison, in the
 * same page load, requires the image rows to hit their exact non-zero counts. A decoder returning
 * nothing at all fails the second half, not the first.
 *
 * DQK's `8X8DB`/`8X8DC` rows (423 + 376) are the two worth knowing about: 305 of those 799 frames
 * are real, successfully decoded 8x1 stubs - 76 blank on the DOS twin as well, 229 the mirror half
 * the Amiga master omits (docs/engine/research/dqk-amiga-glib-frame-variant.md). They are counted
 * because that is what they decode to. Pinning the totals here is what would make a later decision
 * to stop counting them visible instead of silent.
 */
async function runAmigaManifestView(browser, gameId, label, expectRows, total) {
  const errors = [];
  const bad = [];
  let rendered = 0;
  let seen = [];
  const page = await browser.newPage();
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  try {
    await page.goto(`${BASE}/?game=${gameId}`, { waitUntil: 'networkidle2', timeout: 120000 });
    await page.waitForFunction('window.__rendered !== undefined', { timeout: 180000 });
    rendered = await page.evaluate(() => window.__rendered);
    seen = await page.evaluate(() => [...document.querySelectorAll('.file-head')].map((head) => {
      let grid = head.nextElementSibling;
      while (grid && !grid.classList.contains('frame-grid') && !grid.classList.contains('file-head')) {
        grid = grid.nextElementSibling;
      }
      return [
        head.querySelector('.file-name')?.textContent?.trim() ?? '',
        grid?.classList.contains('frame-grid') ? grid.querySelectorAll('canvas').length : 0,
      ];
    }));
  } catch (e) {
    errors.push(`${gameId}-view: ${e.message}`);
  }
  await page.close();

  // Compared as a sorted MULTISET of (row label, frame count) pairs, not positionally: the
  // dashboard groups rows by category, so DOM order is not manifest order and asserting it would
  // pin a presentation decision as if it were a decode fact. A multiset still catches everything
  // that matters here -- a row gaining or losing frames, a row vanishing, a row appearing -- and,
  // unlike a name-keyed lookup, it keeps Curse's two identically-labelled "8X8D (shared tiles)"
  // rows (65 and 1260) as two separate entries that must BOTH be present.
  const norm = (pairs) => pairs.map(([n, c]) => `${n}␀${c}`).sort();
  const got = norm(seen);
  const want = norm(expectRows);
  if (seen.length !== expectRows.length) {
    errors.push(`row count ${seen.length}, expected ${expectRows.length}`);
  }
  const missing = want.filter((w) => !got.includes(w));
  const extra = got.filter((g) => !want.includes(g));
  for (const w of missing) errors.push(`missing row: ${w.replace('␀', ' = ')}`);
  for (const g of extra) errors.push(`unexpected row: ${g.replace('␀', ' = ')}`);
  if (rendered !== total) errors.push(`whole manifest rendered ${rendered} frames (expected ${total})`);

  const pass = errors.length === 0 && bad.length === 0;
  return {
    id: `${gameId}-view`,
    label: `${label} renders from its own WHDLoad install: ${total} frames across ${expectRows.length} manifest rows, exact`,
    rendered,
    min: total,
    errors: pass ? [] : [...errors, JSON.stringify(seen)],
    bad,
    pass,
  };
}


