async function runLateGen1SpritView(browser) {
  const errors = [];
  const bad = [];
  const seen = [];
  // SPRIT rows prove the compressed-picture near/mid/far triple. The tile rows prove the OTHER
  // multi-frame kind is not truncated either — both go through the same `MULTI_FRAME_KINDS`
  // fallback in `framesFromDecoded`, and a regression to per-block `.image` shows here as the
  // block count (4, 6, 3, 7, 4, 8, 1) instead of the tile count.
  //
  // The PIC rows prove the frame COUNT is read from the right field. Both manifests label these
  // "animated scenes", and the animation is exactly the multi-frame case. Reading the count from
  // the word at `recordStart` instead of the DAX header's `item_count` at byte 8 shows here as
  // 41 instead of 81 for Pools and 122 instead of 130 across the two Treasures files.
  //
  // `8X8D1` is the CONTROL, and it is the reason this list is measured rather than assumed: it
  // decodes to 6 images for 6 blocks and that is CORRECT. Its family is claimed earlier in
  // `decodeDax` by the GAME.EXE-derived mode-2 classifier, which reads each block as one tall
  // tile SHEET rather than N tiles. A first draft of this case asserted 1536 here from the
  // Python side's chunky reading of the same bytes and was wrong; pinning 6 keeps the two
  // readings from being silently swapped later.
  const EXPECT = [
    { game: 'pools-of-darkness', file: 'SPRIT1', frames: 87 },
    { game: 'pools-of-darkness', file: 'BORDERS', frames: 44 },
    { game: 'pools-of-darkness', file: 'DUNGCOM', frames: 156 },
    { game: 'pools-of-darkness', file: 'WILDCOM', frames: 120 },
    { game: 'pools-of-darkness', file: '8X8D1', frames: 6 },
    { game: 'pools-of-darkness', file: 'PIC1 ', frames: 81 },
    { game: 'treasures-of-the-savage-frontier', file: 'SPRIT1', frames: 39 },
    // R5 (2026-09-02): +6 each. Treasures' 798-byte records decode as VGA palette-only tables
    // (`kind: 'vga-palette-record'`), and `framesFromDecoded`'s generic `b.image` branch admits
    // them, so each shows as a swatch card. 66->72 and 64->70 is that arm being reachable, which
    // is the whole reason the kind was allowed to reach the dashboard rather than only its tests.
    { game: 'treasures-of-the-savage-frontier', file: 'PIC1 ', frames: 72 },
    { game: 'treasures-of-the-savage-frontier', file: 'PIC1A', frames: 70 },
    { game: 'treasures-of-the-savage-frontier', file: 'BORD ', frames: 137 },
    { game: 'treasures-of-the-savage-frontier', file: 'BORDERS', frames: 44 },
    { game: 'treasures-of-the-savage-frontier', file: 'DUNGCOM', frames: 208 },
    { game: 'treasures-of-the-savage-frontier', file: 'WILDCOM', frames: 40 },
  ];
  const WANT = EXPECT.reduce((n, w) => n + w.frames, 0);
  let rendered = 0;
  for (const game of [...new Set(EXPECT.map((w) => w.game))]) {
    const page = await browser.newPage();
    page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
    page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
    watchHttp(page, bad, { errors });
    try {
      await page.goto(`${BASE}/?game=${game}`, { waitUntil: 'networkidle2', timeout: 90000 });
      await page.waitForFunction('window.__rendered !== undefined', { timeout: 120000 });
      // `.file-name` carries the manifest LABEL, not the basename, so match on the stem.
      const rows = await page.evaluate((names) => {
        const out = {};
        for (const name of names) {
          const head = [...document.querySelectorAll('.file-head')].find((el) =>
            (el.querySelector('.file-name')?.textContent?.trim() ?? '').startsWith(name),
          );
          if (!head) { out[name] = null; continue; }
          // The grid follows the head, but a note row can sit between them.
          let grid = head.nextElementSibling;
          while (grid && !grid.classList.contains('frame-grid') && !grid.classList.contains('file-head')) {
            grid = grid.nextElementSibling;
          }
          out[name] = {
            count: head.querySelector('.file-count')?.textContent?.trim() ?? '',
            canvases: grid?.classList.contains('frame-grid') ? grid.querySelectorAll('canvas').length : 0,
          };
        }
        return out;
      }, EXPECT.filter((w) => w.game === game).map((w) => w.file));
      for (const want of EXPECT.filter((w) => w.game === game)) {
        const row = rows[want.file];
        seen.push(`${game}/${want.file}=${JSON.stringify(row)}`);
        if (!row) { errors.push(`${game}: no ${want.file} row in the dashboard`); continue; }
        if (row.count !== `${want.frames} frames`) {
          errors.push(`${game}/${want.file}: "${row.count}" (expected "${want.frames} frames")`);
        }
        // The count text alone would still read as a pass if no frame reached the DOM.
        if (row.canvases !== want.frames) {
          errors.push(`${game}/${want.file}: ${row.canvases} frame cards (expected ${want.frames})`);
        }
        rendered += row.canvases;
      }
    } catch (e) {
      errors.push(`late-gen1-sprit-view/${game}: ${e.message}`);
    }
    await page.close();
  }
  const pass = errors.length === 0 && bad.length === 0 && rendered === WANT;
  return {
    id: 'late-gen1-sprit-view',
    label: 'Asset browser: late-Gen1 SPRIT triples and multi-item tile banks are surfaced whole',
    rendered,
    min: WANT,
    errors: pass ? [] : [...errors, ...seen],
    bad,
    pass,
  };
}

// Direct NWN preview route: this is the visible browser surface for "what was extracted"
// beyond the generic manifest dashboard. It should render real art frames plus data probes.
async function runNwnPreview(browser) {
  const page = await browser.newPage();
  const errors = [];
  const bad = [];
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  watchHttp(page, bad, { errors });
  let rendered = -1;
  let headerText = '';
  let statusText = '';
  let mapCards = 0;
  let tableRows = 0;
  let catalogueRows = 0;
  let nonBlank = 0;
  let monitmRow = '';
  let visibleAssets = [];
  try {
    await page.goto(`${BASE}/?nwn=1`, { waitUntil: 'networkidle2', timeout: 45000 });
    await page.waitForFunction('window.__rendered !== undefined', { timeout: 45000 });
    ({ rendered, headerText, statusText, mapCards, tableRows, catalogueRows, nonBlank, monitmRow, visibleAssets } = await page.evaluate(() => {
      const canvases = [...document.querySelectorAll('canvas')];
      let painted = 0;
      for (const c of canvases.slice(0, 24)) {
        const ctx = c.getContext('2d');
        if (!ctx || !c.width || !c.height) continue;
        const data = ctx.getImageData(0, 0, Math.min(c.width, 32), Math.min(c.height, 32)).data;
        for (let i = 0; i < data.length; i += 4) {
          if (data[i] || data[i + 1] || data[i + 2]) { painted++; break; }
        }
      }
      const text = document.body.textContent ?? '';
      const required = ['COMSPR.DAX', 'DUNGCOM.DAX', 'CPIC.DAX', 'BODY.DAX', 'CHEAD.DAX'];
      // MONITM's row must NAME its loot, not just count blocks. NWN's code table lives in
      // GAME.EXE, not VOCAB.TXT, and the decoder that recovered it had no caller until
      // 2026-08-26; this is the assertion that proves the wiring is live rather than merely
      // imported. The row is found by its own first cell so a stray match elsewhere on the
      // dashboard cannot satisfy it.
      let monitmRow = '';
      for (const tr of document.querySelectorAll('.nwn-data-table tbody tr')) {
        if (tr.cells[0]?.textContent?.trim() === 'MONITM.DAX') monitmRow = tr.textContent ?? '';
      }
      return {
        rendered: window.__rendered ?? 0,
        headerText: document.querySelector('.nwn-header')?.textContent ?? '',
        statusText: document.querySelector('#status')?.textContent ?? '',
        mapCards: document.querySelectorAll('.nwn-map-card').length,
        tableRows: document.querySelectorAll('.nwn-data-table tbody tr').length,
        catalogueRows: document.querySelectorAll('.nwn-map-catalogue tbody tr').length,
        nonBlank: painted,
        monitmRow,
        visibleAssets: required.filter((name) => text.includes(name)),
      };
    }));
  } catch (e) {
    errors.push(`nwn-preview: ${e.message}`);
  }
  await page.close();
  const pass =
    /Neverwinter Nights \(DOS\/AOL\)/i.test(headerText) &&
    rendered > 0 &&
    mapCards > 0 &&
    tableRows >= 34 &&
    catalogueRows === 29 &&
    nonBlank > 0 &&
    /117 loot item\(s\) naming 38 distinct items from 254 GAME\.EXE vocabulary entries/.test(monitmRow) &&
    monitmRow.includes('Composite Long Bow') &&
    monitmRow.includes('Morning Star') &&
    visibleAssets.length === 5 &&
    errors.length === 0 &&
    bad.length === 0;
  return {
    id: 'nwn-preview',
    label: 'NWN extracted-asset preview route',
    rendered,
    min: 1,
    errors: pass ? [] : [...errors, `header="${headerText}" status="${statusText}" maps=${mapCards} rows=${tableRows} catalogue=${catalogueRows} painted=${nonBlank} assets=${visibleAssets.join(',')} monitm="${monitmRow}"`],
    bad,
    pass,
  };
}

// M7.S1 — proves a Library entry's own `assetSource` is genuinely READ during startExplore(),
// not silently ignored in favour of the bundled repo copy. Registers a Library entry via the
// synthetic seam with deliberately-garbage bytes for CoK's required DAX archives (no native
// folder access is automatable in a headless browser), then drives the real DOM click path
// (`.lib-entry` → onLibrarySelect(entry)`, the exact entry object, not a serialized copy) and
// asserts the dungeon load fails loudly — if the assetSource were ignored, this would silently
// succeed using the real bundled CoK data instead, which is exactly the bug this guards against.
// Self-contained (no dependency on local game data), so it also runs in "no data" SKIP mode.
async function runAssetSourceWiring(browser) {
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' && !IGNORE_CONSOLE.some((re) => re.test(m.text()))) errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  let rendered = -1;
  let statusText = '';
  let matched = false;
  try {
    await page.goto(`${BASE}/`, { waitUntil: 'networkidle2', timeout: 45000 });
    await page.waitForFunction(
      'window.__greybox && typeof window.__greybox.addFromEntriesWithAssets === "function"',
      { timeout: 45000 },
    );
    const match = await page.evaluate(
      (files, assets) => window.__greybox.addFromEntriesWithAssets('picked-cok', files, assets),
      COK_DOS_FILES,
      COK_ASSET_SOURCE_GARBAGE,
    );
    matched = !!match && match.profileId === 'champions-of-krynn' && match.platform === 'DOS';
    await page.waitForSelector('.lib-entry', { timeout: 10000 });
    await page.click('.lib-entry');
    await page.waitForFunction('window.__rendered !== undefined', { timeout: 20000 });
    await new Promise((r) => setTimeout(r, 500)); // let the click-triggered async load settle
    rendered = await page.evaluate('window.__rendered');
    statusText = await page.evaluate(() => document.querySelector('#status')?.textContent || '');
  } catch (e) {
    errors.push(`asset-source-wiring: ${e.message}`);
  }
  await page.close();
  const failedAsExpected = rendered === 0 && /could not load (?:dungeon|cok opening)/i.test(statusText);
  const pass = matched && failedAsExpected && errors.length === 0;
  return {
    id: 'asset-source-wiring',
    label: "Library: booted entry reads its OWN assetSource, not the bundled copy (M7.S1)",
    rendered,
    min: 0,
    errors: pass ? [] : [...errors, `matched=${matched} status="${statusText}"`],
    bad: [],
    pass,
  };
}

// M7.S2 — the same wiring proof as runAssetSourceWiring, for DQK's separate Gen2/HLIB load path
