    const beforeLen = await page.evaluate('window.__combat.logLen()');
    const beforeOver = await page.evaluate('window.__combat.isOver()');
    await page.evaluate('window.__combat.quick()');
    const afterCurrent = await page.evaluate('window.__combat.current()');
