      // Amiga: a real parsed score + sampled SFX. DOS: music honestly reports undecoded.
      await page.evaluate("window.__audio.setPlatform('Amiga')");
      sfxCount = await page.evaluate('window.__audio.sfxCount()');
      const amigaHasScore = await page.evaluate('window.__audio.hasScore()');
