        await page.waitForFunction('window.__dqk.combatOpen() && window.__combat', { timeout: 20000 });
        const enemyCount = await page.evaluate('window.__combat.livingEnemies().length'); // a DQK foe is on the field
        // The battle map DQK fights on, pinned because it used to be a DISCLOSED GAP and is now a
