      // additive — the proof the pinned 12-byte operator map is correct. Skipped when the bank is absent.
      const oplClarinet = await page.evaluate('window.__dqk.previewOplNote(51, 60)');
      const oplDrum = await page.evaluate('window.__dqk.previewOplNote(117, 60)');
